import*as schemas from"har-schema";import Ajv from"ajv";import HARError from"./error";let ajv;export function validate(e,r={}){ajv=ajv||new Ajv({allErrors:!0,schemas:schemas});let t=ajv.getSchema(e+".json");return new Promise((e,n)=>{t(r)?e(r):n(new HARError(t.errors))})}export function afterRequest(e){return validate("afterRequest",e)}export function beforeRequest(e){return validate("beforeRequest",e)}export function browser(e){return validate("browser",e)}export function cache(e){return validate("cache",e)}export function content(e){return validate("content",e)}export function cookie(e){return validate("cookie",e)}export function creator(e){return validate("creator",e)}export function entry(e){return validate("entry",e)}export function har(e){return validate("har",e)}export function header(e){return validate("header",e)}export function log(e){return validate("log",e)}export function page(e){return validate("page",e)}export function pageTimings(e){return validate("pageTimings",e)}export function postData(e){return validate("postData",e)}export function query(e){return validate("query",e)}export function request(e){return validate("request",e)}export function response(e){return validate("response",e)}export function timings(e){return validate("timings",e)}